xml.Script:
        Colors[ 0] := 'FFFFFF'; // White
        Colors[ 1] := 'EE0000'; // Red
        Colors[ 2] := '00CC00'; // Green
        Colors[ 3] := '0055EE'; // Light Blue
        Colors[ 4] := 'FFFF00'; // Yellow
        Colors[ 5] := 'FF800A'; // Orange

        sColors[ 0] := '        0102030                ';
        sColors[ 1] := '        2 4 4 1                ';
        sColors[ 2] := '        05 3 20                ';
        sColors[ 3] := '        3 1 1 3                ';
        sColors[ 4] := '        05 3 40                ';
        sColors[ 5] := '        1 4 5 1                ';
        sColors[ 6] := '        0301020                ';
        sColors[ 7] := '0103010 0201020 0203010 0302010';
        sColors[ 8] := '2 2 5 3 3 3 3 1 1 5 2 2 2 1 3 3';
        sColors[ 9] := '01 4 20 01 2 40 02 1 40 05 4 20';
        sColors[10] := '3 3 3 1 2 5 1 2 3 4 5 1 3 3 5 1';
        sColors[11] := '02 5 40 03 2 50 05 2 30 01 2 30';
        sColors[12] := '1 4 1 3 1 4 3 3 1 1 4 2 2 4 1 2';
        sColors[13] := '0203020 0301020 0302030 0102030';
        sColors[14] := '        0301030                ';
        sColors[15] := '        1 2 2 2                ';
        sColors[16] := '        03 1 30                ';
        sColors[17] := '        2 4 5 1                ';
        sColors[18] := '        01 2 40                ';
        sColors[19] := '        3 3 1 2                ';
        sColors[20] := '        0102030                ';

        W := 0.5;
        D := W / 4;

        N := 8;
        c := 0;
        for i := 0 to N do
            for j := 0 to N do
                for k := 0 to N do
                    if ((i = 0) or (j = 0) or (k = 0) or (i = N) or (j = N) or (k = N)) and ((i + j + k) mod 2 = 0) then begin
                        Vx[c] := D * i - W;
                        Vy[c] := D * j - W;
                        Vz[c] := D * k - W;
                        Idx[i,j,k] := IntToStr(c);
                        inc(c);
                    end;

        function GetSIdx(x2, y2);
        begin
            Result := Idx[x + dx1 * x2 + dx2 * y2, y + dy1 * x2 + dy2 * y2, z + dz1 * x2 + dz2 * y2] + ';';
        end;

        function GetColor(x3, y3);
        begin
            substr := copy(sColors[y3], x3, 1);
            Result := Colors[StrToInt(substr)];
        end;

        procedure MakeColoredFace(i, j);
        begin
            S[c] := GetSIdx(i + 1, j) + GetSIdx(i, j - 1) + GetSIdx(i - 1, j) + GetSIdx(i, j + 1);
            Cl[c] := GetColor(cx + i - 1, cy + j - 1);
            IE[c] := -1;
            Inc(c);
        end;

        procedure MakeCornerFace(kx1, ky1, kx2, ky2, kx3, ky3, kc1, kc2);
        begin
            S[c] := GetSIdx(kx1, ky1) + GetSIdx(kx2, ky2) + GetSIdx(kx3, ky3);
            Cl[c] := GetColor(cx + kc1, cy + kc2);
            IE[c] := 2;
            Inc(c);
        end;

        procedure MakeEdgeFace(kx1, ky1, kx2, ky2, kx3, ky3, kc1, kc2);
        begin
            S[c] := GetSIdx(kx1, ky1) + GetSIdx(kx2, ky2) + GetSIdx(kx3, ky3);
            Cl[c] := GetColor(cx + kc1, cy + kc2);
            IE[c] := 3;
            Inc(c);
        end;

        procedure MakeSide(x, y, z, dx1, dy1, dz1, dx2, dy2, dz2, cx, cy);
        // x, y, z - left-top point of side
        // dx1, dy1, dz1 - 1st counting vector
        // dx2, dy2, dz2 - 2nd counting vector
        // cx, cy - left-top letter in sColors
        begin
            for i := 1 to N - 1 do
                for j := 1 to N - 1 do
                    if (i + j) mod 2 = 1 then
                        MakeColoredFace(i,j);

            MakeCornerFace(0,0, 0,2, 2,0,  0,0);
            MakeCornerFace(8,0, 6,0, 8,2,  6,0);
            MakeCornerFace(8,8, 8,6, 6,8,  6,6);
            MakeCornerFace(0,8, 2,8, 0,6,  0,6);

            MakeEdgeFace(2,0, 3,1, 4,0,  2,0);
            MakeEdgeFace(4,0, 5,1, 6,0,  4,0);

            MakeEdgeFace(8,2, 7,3, 8,4,  6,2);
            MakeEdgeFace(8,4, 7,5, 8,6,  6,4);

            MakeEdgeFace(6,8, 5,7, 4,8,  4,6);
            MakeEdgeFace(4,8, 3,7, 2,8,  2,6);

            MakeEdgeFace(0,6, 1,5, 0,4,  0,4);
            MakeEdgeFace(0,4, 1,3, 0,2,  0,2);
        end;

        c := 0;
        MakeSide( 0, N, N,  1, 0, 0,  0,-1, 0,   9, 0); // up
        MakeSide( 0, 0, N,  1, 0, 0,  0, 0,-1,   9, 7); // face
        MakeSide( 0, N, N,  0,-1, 0,  0, 0,-1,   1, 7); // left
        MakeSide( N, 0, N,  0, 1, 0,  0, 0,-1,  17, 7); // right
        MakeSide( N, N, N, -1, 0, 0,  0, 0,-1,  25, 7); // back
        MakeSide( 0, 0, 0,  1, 0, 0,  0, 1, 0,   9,14); // bottom
